<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Factories\HasFactory;
class Product extends Model {use HasFactory;protected $primaryKey='product_id';protected $fillable=['category_id','brand_id','name','slug','description','is_active'];protected $casts=['is_active'=>'boolean'];public function category(){return $this->belongsTo(Category::class,'category_id','category_id');}public function brand(){return $this->belongsTo(Brand::class,'brand_id','brand_id');}public function skus(){return $this->hasMany(ProductSku::class,'product_id','product_id');}public function reviews(){return $this->hasMany(Review::class,'product_id','product_id');}public function wishlists(){return $this->hasMany(Wishlist::class,'product_id','product_id');}public function getDefaultSkuAttribute(){return $this->skus->sortByDesc('sku_id')->first();}public function getAverageRatingAttribute(){return round((float)$this->reviews()->avg('rating'),1);}}
